<?php
 namespace QQWorld\Catalog\Model\Product\Price; class PricePersistence { private $table = 'catalog_product_entity_decimal'; private $attributeResource; private $attributeRepository; private $productIdLocator; private $metadataPool; private $attributeCode; private $attributeId; private $itemsPerOperation = 500; public function __construct( \QQWorld\Catalog\Model\ResourceModel\Attribute $attributeResource, \QQWorld\Catalog\Api\ProductAttributeRepositoryInterface $attributeRepository, \QQWorld\Catalog\Model\ProductIdLocatorInterface $productIdLocator, \QQWorld\Framework\EntityManager\MetadataPool $metadataPool, $attributeCode = '' ) { $this->attributeResource = $attributeResource; $this->attributeRepository = $attributeRepository; $this->attributeCode = $attributeCode; $this->productIdLocator = $productIdLocator; $this->metadataPool = $metadataPool; } public function get(array $skus) { $ids = $this->retrieveAffectedIds($skus); $select = $this->attributeResource->getConnection() ->select() ->from($this->attributeResource->getTable($this->table)); return $this->attributeResource->getConnection()->fetchAll( $select->where($this->getEntityLinkField() . ' IN (?)', $ids) ->where('attribute_id = ?', $this->getAttributeId()) ); } public function update(array $prices) { array_walk($prices, function (&$price) { return $price['attribute_id'] = $this->getAttributeId(); }); $connection = $this->attributeResource->getConnection(); $connection->beginTransaction(); try { foreach (array_chunk($prices, $this->itemsPerOperation) as $pricesBunch) { $this->attributeResource->getConnection()->insertOnDuplicate( $this->attributeResource->getTable($this->table), $pricesBunch, ['value'] ); } $connection->commit(); } catch (\Exception $e) { $connection->rollBack(); throw new \QQWorld\Framework\Exception\CouldNotSaveException( __('Could not save Prices.'), $e ); } } public function delete(array $skus) { $ids = $this->retrieveAffectedIds($skus); $connection = $this->attributeResource->getConnection(); $connection->beginTransaction(); try { foreach (array_chunk($ids, $this->itemsPerOperation) as $idsBunch) { $this->attributeResource->getConnection()->delete( $this->attributeResource->getTable($this->table), [ 'attribute_id = ?' => $this->getAttributeId(), $this->getEntityLinkField() . ' IN (?)' => $idsBunch ] ); } $connection->commit(); } catch (\Exception $e) { $connection->rollBack(); throw new \QQWorld\Framework\Exception\CouldNotDeleteException( __('Could not delete Prices'), $e ); } } public function retrieveSkuById($id, $skus) { foreach ($this->productIdLocator->retrieveProductIdsBySkus($skus) as $sku => $ids) { if (false !== array_key_exists($id, $ids)) { return $sku; } } return null; } private function getAttributeId() { if (!$this->attributeId) { $this->attributeId = $this->attributeRepository->get($this->attributeCode)->getAttributeId(); } return $this->attributeId; } private function retrieveAffectedIds(array $skus) { $affectedIds = []; foreach ($this->productIdLocator->retrieveProductIdsBySkus($skus) as $productIds) { $affectedIds = array_merge($affectedIds, array_keys($productIds)); } return array_unique($affectedIds); } public function getEntityLinkField() { return $this->metadataPool->getMetadata(\QQWorld\Catalog\Api\Data\ProductInterface::class) ->getLinkField(); } } 